# Build the transformed grid: retain each rectangular outline, and fill the interior checkerboard
# with the color whose singleton count matches that frame's checkerboard cell count.
R,C=22,26
g=[[0]*C for _ in range(R)]
# frame (top,left,bottom,right,border,fill); fill starts at interior top-left
frames=[(1,3,6,11,1,4),(10,2,13,5,2,8),(9,11,16,21,3,5)]
for top,left,bottom,right,border,fill in frames:
    for c in range(left,right+1):
        g[top][c]=border
        g[bottom][c]=border
    for r in range(top,bottom+1):
        g[r][left]=border
        g[r][right]=border
    for r in range(top+1,bottom):
        for c in range(left+1,right):
            if (r-(top+1)+c-(left+1))%2==0:
                g[r][c]=fill
assert len(g)==22 and all(len(row)==26 for row in g)
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')
